<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import KeyPanel from '../components/KeyPanel.vue'
import ApiGuide from '../components/ApiGuide.vue'
import ThemeToggle from '../components/ThemeToggle.vue'
import { baseURL, date, names, number, platformLink, platforms, portalLink, safe, session, statusName } from '../modules/session'
import { copy, useWorkspace } from '../modules/workspace'
import type { Account, Platform } from '../types'
const route = useRoute()
const p = (import.meta.env.DEV ? route.params.platform : session.platform) as Platform
const { accounts, catalog, pool, quota, checkins, checkinRows, credential, login, region, tab, auto, errors, busy, warning, refresh, refreshPool, refreshAccounts, refreshModels, refreshQuota, refreshCheckins, claim, action, importCredential, readFile, download, startLogin, cancelLogin } = useWorkspace(p)
const search = ref(''), selected = ref('')
const tabs = computed(() => p === 'gateway' ? [{ id: 'pool', label: '号池总览' }, { id: 'models', label: '模型目录' }, { id: 'guide', label: 'API 指南' }] : [{ id: 'accounts', label: '账号管理' }, { id: 'models', label: '模型目录' }, { id: 'checkin', label: '每日签到' }, { id: 'quota', label: '额度监控' }, { id: 'guide', label: 'API 指南' }])
const models = computed(() => p === 'gateway' ? pool.value?.models || [] : catalog.value?.data || [])
const filtered = computed(() => models.value.filter(m => `${m.id} ${m.name || ''} ${(m.canonicalIds || []).join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
const title = computed(() => tabs.value.find(t => t.id === tab.value)?.label || '')
const descriptions: Record<string, string> = { pool: '查看跨平台账号资格、余额与当前可调度模型。', accounts: '连接官方账号，管理凭据与服务调用状态。', models: '发现当前服务可用的模型，并快速用于 API 接入。', checkin: '查询每日状态，按需领取账号奖励。', quota: '查看真实额度与使用量，了解每个账号的状态。', guide: '配置你的应用，或发送一条消息验证连接。' }
const eligible = (a: Account) => a.enabled === true && a.status === 'ready' && (a.unlimited === true || typeof a.remaining === 'number' && a.remaining > 0) && !a.quotaError && !a.modelsError && !!a.models?.length
const quotaTotals = computed(() => {
  const groups = new Map<string, { sum: number; known: number; count: number }>()
  for (const account of quota.value?.accounts || []) {
    const unit = (p === 'qoder' ? (account.region === 'cn' ? '国内版' : account.region === 'global' ? '国际版' : '未知区域') + ' · ' : '') + (account.unit || quota.value?.unit || '未知单位')
    const group = groups.get(unit) || { sum: 0, known: 0, count: 0 }
    group.count++
    if (typeof account.remaining === 'number' && Number.isFinite(account.remaining)) { group.sum += account.remaining; group.known++ }
    groups.set(unit, group)
  }
  return Array.from(groups, ([unit, group]) => ({ unit, ...group }))
})
const quotaText = (a: Account) => a.unlimited ? '不限额度' : number(a.remaining) + ' ' + (a.unit || quota.value?.unit || '')
function selectModel(id: string) { selected.value = id; tab.value = 'guide'; void copy(id) }
</script>
<template>
  <div class="workspace" :class="p">
    <aside class="sidebar"><a class="brand" :href="portalLink()"><span class="brand-mark">K</span>KleeAPI</a><a class="back-link" :href="portalLink()">← 返回门户</a><div class="workspace-badge"><span class="platform-symbol">{{ p === 'gateway' ? 'K' : names[p].slice(0, 1) }}</span><div><strong>{{ names[p] }}</strong><small>独立工作空间</small></div></div><p class="nav-label">工作空间</p><nav aria-label="工作空间导航"><button v-for="item in tabs" :key="item.id" :class="{ active: tab === item.id }" :aria-current="tab === item.id ? 'page' : undefined" @click="tab = item.id"><span class="nav-dot" />{{ item.label }}</button></nav><div class="sidebar-bottom"><span class="local-label"><i /> 本地服务</span><code>{{ baseURL(p) }}</code><a v-for="platform in platforms.filter(x => x !== p)" :key="platform" :href="platformLink(platform)">{{ names[platform] }} ↗</a></div></aside>
    <main class="workspace-main"><header class="workspace-top"><span>KleeAPI <span class="slash">/</span> {{ names[p] }} <span class="slash">/</span> {{ title }}</span><div class="theme-header-actions"><span class="local-label"><i /> LOCAL</span><ThemeToggle /></div></header><div class="page-content"><section class="page-heading"><div><p class="eyebrow">{{ names[p] }} WORKSPACE</p><h1>{{ title }}</h1><p class="muted">{{ descriptions[tab] }}</p></div><span class="workspace-version">OPENAI COMPATIBLE</span></section>
    <KeyPanel :platform="p" @saved="refresh" />

    <section v-if="tab === 'pool'" class="panel"><div class="section-heading"><div><h2>跨平台号池</h2><p class="muted">{{ pool ? '更新于 ' + date(pool.fetchedAt) : '保存网关 Key 后读取实际号池。' }}</p></div><el-button :loading="busy.pool" @click="refreshPool(true)">刷新号池</el-button></div><el-alert v-if="errors.pool" :title="errors.pool + (pool ? ' 显示上次快照，当前可用性待确认。' : '')" type="error" :closable="false" /><div class="stats"><div><span>已连接账号</span><strong>{{ pool ? pool.accounts.length : '—' }}</strong></div><div><span>可参与调度</span><strong>{{ pool ? pool.accounts.filter(eligible).length : '—' }}</strong></div><div><span>发现模型</span><strong>{{ pool ? models.length : '—' }}</strong></div></div><el-alert v-for="error in pool?.platforms?.filter(x => x.error)" :key="error.platform" :title="names[error.platform] + '：' + safe(error.error)" type="warning" :closable="false" /><div v-if="pool?.accounts.length" class="rows"><article v-for="a in pool.accounts" :key="a.platform + ':' + a.uid" class="account-row"><span class="avatar">{{ (a.nickname || names[a.platform || 'gateway']).slice(0, 1) }}</span><div class="account-info"><h3>{{ a.nickname || a.uid }} <el-tag :type="eligible(a) ? 'success' : 'warning'">{{ a.enabled === false ? '已停用' : a.status === 'expired' ? '认证失效' : eligible(a) ? '可参与调度' : '暂不可调度' }}</el-tag></h3><p class="muted">{{ names[a.platform || 'gateway'] }} · {{ a.region || '未知区域' }} · {{ a.uid }}<br>余额 {{ quotaText(a) }} · {{ a.models?.length ?? '未知' }} 个模型 · 处理中 {{ a.inFlight ?? 0 }}</p><p v-if="a.quotaError || a.modelsError" class="error-text">{{ a.quotaError ? '额度：' + safe(a.quotaError) : '' }} {{ a.modelsError ? '模型：' + safe(a.modelsError) : '' }}</p></div></article></div><el-empty v-else description="暂无账号。请在各平台管理页连接账号。" /></section>

    <template v-if="tab === 'accounts'">
      <section class="panel"><div class="section-heading"><h2>已连接账号 <span class="count">{{ accounts.length }}</span></h2><el-button :loading="busy.accounts" @click="refreshAccounts">刷新账号</el-button></div><el-alert v-if="warning || errors.accounts" :title="warning || errors.accounts" type="warning" :closable="false" /><div class="stats"><div><span>已连接</span><strong>{{ accounts.length }}</strong></div><div><span>已启用</span><strong>{{ accounts.filter(a => a.enabled).length }}</strong></div><div><span>当前账号</span><strong class="stat-name">{{ accounts.find(a => a.active)?.nickname || accounts.find(a => a.active)?.uid || '未选择' }}</strong></div></div><div class="rows"><article v-for="a in accounts" :key="a.uid" class="account-row"><span class="avatar">{{ (a.nickname || 'A').slice(0, 1).toUpperCase() }}</span><div class="account-info"><h3>{{ a.nickname || a.uid }} <el-tag v-if="a.active" type="success">当前账号</el-tag> <el-tag :type="a.status === 'ready' ? 'success' : 'warning'">{{ statusName(a.status) }}</el-tag></h3><p class="muted">{{ a.region || '未知区域' }} · {{ a.uid }} · 来源 {{ a.source || '未知' }}<br>有效期 {{ date(a.expiresAt) }} · 余额 {{ number(a.credits) }}<span v-if="p === 'qoder'"> {{ a.region === 'cn' ? 'Qoder CN' : 'Qoder Global' }} Credits</span><br v-if="a.email || a.plan"><span v-if="a.email">{{ a.email }} · </span>{{ a.plan }}</p><div class="actions"><el-button :disabled="busy.action || a.active || !a.enabled || a.status === 'expired'" @click="action(a, 'active')">设为当前</el-button><el-button :disabled="busy.action" @click="action(a, 'enabled')">{{ a.enabled ? '停用' : '启用' }}</el-button><el-button :disabled="busy.action" @click="action(a, 'refresh')">续期</el-button><el-button :disabled="busy.action" @click="action(a, 'export')">导出凭据</el-button><el-button :disabled="busy.action" type="danger" plain @click="action(a, 'delete')">删除</el-button></div></div></article></div><el-empty v-if="!accounts.length" description="尚无账号。通过官方登录或导入 JSON 开始。" /></section>
      <div class="connection-grid"><section class="panel"><p class="eyebrow">CONNECT ACCOUNT</p><h2>官方登录</h2><p class="muted">在官方页面完成授权后，自动将账号导入本地。</p><el-form label-position="top"><el-form-item label="账号区域"><el-select v-model="region" :disabled="p === 'trae' || !!login"><el-option label="国内版" value="cn" /><el-option label="国际版" value="global" /></el-select></el-form-item></el-form><p v-if="p === 'trae'" class="muted">Trae 使用本地回调 http://127.0.0.1:18080/authorize，请保持此页面打开。</p><div class="actions"><el-button type="primary" :loading="busy.login" :disabled="!!login" @click="startLogin">官方登录</el-button><el-button v-if="p === 'workbuddy'" :loading="busy.import" @click="importCredential(true)">读取桌面登录</el-button><el-button v-if="login" :loading="busy.login" @click="cancelLogin">取消登录</el-button></div><div v-if="login" class="login-status" role="status"><p>等待官方授权，完成后自动导入…</p><a :href="login.url" target="_blank" rel="noopener noreferrer">重新打开官方登录页面 ↗</a></div></section>
      <section class="panel"><p class="eyebrow">CREDENTIALS</p><h2>凭据 JSON</h2><p class="muted">包含敏感凭据，请妥善保存。只在此编辑区展示完整内容。</p><el-input v-model="credential" type="textarea" :rows="6" aria-label="凭据 JSON" placeholder="粘贴完整凭据 JSON 或平台支持的凭据字符串" /><label class="file-label">选择 JSON 文件<input type="file" accept=".json,application/json" @change="readFile"></label><div class="actions"><el-button type="primary" :loading="busy.import" @click="importCredential()">导入账号</el-button><el-button :disabled="!credential" @click="download">导出 JSON</el-button><el-button :disabled="!credential" @click="credential = ''">清空</el-button></div></section></div>
    </template>

    <section v-if="tab === 'models'" class="panel"><div class="section-heading"><div><h2>模型目录 <span class="count">{{ models.length }}</span></h2><p class="muted">{{ p === 'gateway' ? '来源：网关号池' : catalog ? '来源：' + (catalog.source === 'account' ? '当前账号' : '服务端缓存') + ' · ' + date(catalog.fetchedAt) : '显式刷新后显示实际可用模型。' }}</p></div><el-button :loading="busy.models || busy.pool" @click="p === 'gateway' ? refreshPool(true) : refreshModels()">刷新模型</el-button></div><el-alert v-if="errors.models || errors.pool" :title="errors.models || errors.pool" type="error" :closable="false" /><el-input v-model="search" placeholder="搜索模型名称或 ID" clearable aria-label="搜索模型" class="search" /><div class="model-grid"><article v-for="m in filtered" :key="m.id" class="model-card"><span class="model-indicator" /><h3>{{ m.name || m.id }}</h3><code>{{ m.id }}</code><p v-if="p === 'gateway'" class="muted">{{ m.availableAccounts ?? '未知' }} 个可用账号<br>{{ m.canonicalIds?.join(' · ') }}</p><el-button @click="selectModel(m.id)">复制 ID 并用于示例</el-button></article></div><el-empty v-if="!filtered.length" description="没有可展示的模型，请刷新目录或检查搜索条件。" /></section>

    <section v-if="tab === 'checkin'" class="panel"><div class="section-heading"><div><h2>每日签到</h2><p class="muted">{{ checkins ? '更新于 ' + date(checkins.fetchedAt) : '进入页面自动查询签到状态。' }}</p></div><div class="actions"><el-button :loading="busy.query" @click="refreshCheckins">刷新状态</el-button><el-button :disabled="busy.query" @click="claim(false)">当前账号签到</el-button><el-button type="primary" :disabled="busy.query" @click="claim(true)">全部账号签到</el-button></div></div><el-alert v-if="errors.checkins" :title="errors.checkins + ' 显示上次结果，状态可能已变化。'" type="error" :closable="false" /><p class="muted">共 {{ checkinRows.length }} 个账号 · 已签 {{ checkinRows.filter(a => a.checkedIn === true || ['already','claimed'].includes(a.status || '')).length }} · 未签 {{ checkinRows.filter(a => a.enabled !== false && !['no_activity','disabled','skipped'].includes(a.status || '') && a.checkedIn === false).length }} · 其余为未知、无活动或停用</p><div class="result-grid"><article v-for="a in checkinRows" :key="a.uid" class="result-card"><div class="section-heading"><h3>{{ a.nickname || a.uid }}</h3><el-tag :type="['claimed','already'].includes(a.status || '') ? 'success' : 'info'">{{ statusName(a.status) }}</el-tag></div><p>{{ safe(a.message || statusName(a.status)) }}</p><p class="muted">{{ a.uid }} · {{ a.region || '未知区域' }}</p><p v-if="a.reward != null">奖励 {{ a.reward }}</p><p v-if="a.startsAt || a.endsAt" class="muted">{{ date(a.startsAt) }} → {{ date(a.endsAt) }}</p><p v-if="a.balanceBefore != null || a.balanceAfter != null" class="balance">{{ number(a.balanceBefore) }} → {{ number(a.balanceAfter) }}</p></article></div><el-empty v-if="!checkinRows.length" description="请先连接账号。" /></section>

    <section v-if="tab === 'quota'" class="panel"><div class="section-heading"><div><h2>额度监控</h2><p class="muted">{{ quota ? '更新于 ' + date(quota.fetchedAt) : '尚无成功刷新的数据。' }}</p></div><div class="actions"><el-checkbox v-model="auto">每 60 秒刷新</el-checkbox><el-button :loading="busy.query" @click="refreshQuota">刷新额度</el-button></div></div><el-alert v-if="errors.quota" :title="errors.quota + ' 显示上次数据，额度可能已变化。'" type="error" :closable="false" /><p class="muted">未知额度不会记作零；不同区域、单位的额度分别展示。</p><div class="quota-totals"><article v-for="group in quotaTotals" :key="group.unit"><strong>{{ group.known ? number(group.sum) : '未知' }}</strong><span>{{ group.unit }}</span><p class="muted">{{ group.known }}/{{ group.count }} 个账号有余额数据<span v-if="group.known &lt; group.count"> · 合计不含未知余额</span></p></article></div><div class="result-grid"><article v-for="a in quota?.accounts || []" :key="a.uid" class="result-card"><div class="section-heading"><h3>{{ a.nickname || a.uid }}</h3><el-tag :type="a.enabled === false ? 'info' : a.status === 'ready' ? 'success' : 'warning'">{{ a.enabled === false ? '已停用' : statusName(a.status) }}</el-tag></div><p class="muted">{{ a.region || '未知区域' }} · {{ a.uid }}<br>{{ a.plan || '套餐未知' }}</p><strong class="quota-value">{{ quotaText(a) }}</strong><p class="muted">已用 {{ number(a.used) }} · 总量 {{ number(a.limit) }}</p><p v-if="a.quotaError" class="error-text">{{ safe(a.quotaError) }}</p><p class="muted">凭据到期 {{ date(a.expiresAt) }}</p><el-progress v-if="typeof a.remaining === 'number' && typeof a.limit === 'number' && a.limit > 0" :percentage="Math.max(0, Math.min(100, Math.round(a.remaining / a.limit * 100)))" :stroke-width="5" /><p v-if="a.checkin" class="muted">签到：{{ a.checkin.enabled === false ? '无签到活动' : a.checkin.checkedIn === true ? (p === 'qoder' ? '本轮已签' : '今日已签') : a.checkin.checkedIn === false ? (p === 'qoder' ? '本轮未签' : '今日未签') : '状态未知' }}<span v-if="a.checkin.reward != null"> · 奖励 {{ a.checkin.reward }}</span></p><p v-if="a.checkin?.startsAt || a.checkin?.endsAt" class="muted">{{ date(a.checkin.startsAt) }} → {{ date(a.checkin.endsAt) }}</p><p v-if="a.checkinError" class="error-text">签到：{{ safe(a.checkinError) }}</p><details v-if="a.packages?.length" class="quota-packages"><summary>额度包明细（{{ a.packages.length }}）</summary><div v-for="(pack, index) in a.packages" :key="index"><h3>{{ pack.name || pack.type || '额度包' }}</h3><p class="muted">剩余 {{ number(pack.remaining) }} / {{ number(pack.limit) }} {{ pack.unit || a.unit }}<br>已用 {{ number(pack.used) }}<span v-if="pack.expiresAt"><br>到期 {{ date(pack.expiresAt) }}</span></p></div></details></article></div><el-empty v-if="!quota?.accounts.length" description="暂无额度快照。请连接账号后刷新。" /></section>
    <ApiGuide v-if="tab === 'guide'" :platform="p" :models="models" :selected="selected" />
    <footer class="workspace-footer">{{ names[p] }} · {{ baseURL(p) }} <span>本地管理 / 由你掌控</span></footer></div></main>
  </div>
</template>
